import boto3
from typing import Dict, List, Any, Optional

def safe_float(value: Optional[str]) -> Optional[float]:
    if value is None:
        return None
    try:
        return float(value)
    except ValueError:
        return None

def extract_and_normalize_expenses(document_path: str) -> Dict[str, Any]:
    with open(document_path, 'rb') as file:
        document_bytes = file.read()

    client = boto3.client('textract')
    response = client.analyze_expense(
        Document={'Bytes': document_bytes}
    )

    if not response.get('ExpenseDocuments'):
        return {"error": "No expense documents detected"}

    expense_doc = response['ExpenseDocuments'][0]

    # Extract summary fields
    summary: Dict[str, str] = {}
    for field in expense_doc['SummaryFields']:
        field_type = field['Type']['Text']
        text = field['ValueDetection']['Text']
        summary[field_type] = text

    # Extract line items
    line_items: List[Dict[str, Any]] = []
    for group in expense_doc.get('LineItemGroups', []):
        item_data = {
            'description': None,
            'quantity': None,
            'unit_price': None,
            'total': None
        }
        for line_item in group['LineItems']:
            item_type = line_item['Type']['Text']
            text = line_item['TextDetection']['Text']
            if item_type == 'DESCRIPTION':
                item_data['description'] = text
            elif item_type == 'QUANTITY':
                item_data['quantity'] = safe_float(text)
            elif item_type == 'UNIT_PRICE':
                item_data['unit_price'] = safe_float(text)
            elif item_type == 'TOTAL_PRICE':
                item_data['total'] = safe_float(text)

        if item_data['description']:
            line_items.append(item_data)

    # Normalized schema
    normalized = {
        'vendor_name': summary.get('INVOICE_VENDOR_NAME'),
        'vendor_address': summary.get('INVOICE_VENDOR_ADDRESS'),
        'invoice_date': summary.get('INVOICE_INVOICE_DATE'),
        'due_date': summary.get('INVOICE_DUE_DATE'),
        'total_amount': safe_float(summary.get('INVOICE_INVOICE_TOTAL')),
        'tax_amount': safe_float(summary.get('INVOICE_TOTAL_TAX')),
        'line_items': line_items
    }

    return normalized
